import React from 'react';

function App() {
  return (
    <div style={{ 
      padding: '20px', 
      textAlign: 'center',
      backgroundColor: '#e6f2ff',
      minHeight: '100vh'
    }}>
      <h1 style={{ color: '#1e3a8a', fontSize: '48px' }}>PrimeStone Investment</h1>
      <p style={{ color: '#2563eb', fontSize: '24px' }}>Secure • Transparent • Profitable</p>
      <div style={{ marginTop: '40px' }}>
        <button style={{ 
          backgroundColor: '#2563eb', 
          color: 'white', 
          padding: '12px 24px',
          border: 'none',
          borderRadius: '8px',
          margin: '0 10px',
          cursor: 'pointer',
          fontSize: '16px'
        }}>
          Login
        </button>
        <button style={{ 
          backgroundColor: '#fbbf24', 
          color: '#1e3a8a', 
          padding: '12px 24px',
          border: 'none',
          borderRadius: '8px',
          margin: '0 10px',
          cursor: 'pointer',
          fontSize: '16px'
        }}>
          Register
        </button>
      </div>
    </div>
  );
}

export default App;
